def verifier(assign):
    # Recompute the unique smallest x in [1, m] that maximizes the survival length in (0, b),
    # for the sequence a_1 = a, a_2 = x, a_n = c a_{n-2} - a_{n-1} (n ≥ 3).
    from fractions import Fraction as F

    def best_x_and_length(a, b, c, m):
        if not (isinstance(a, int) and isinstance(b, int) and isinstance(c, int) and isinstance(m, int)):
            return None, 0
        if not (a > 0 and b > 0 and m >= 1 and c >= 2):
            return None, 0
        if not (a < b):
            return None, 0
        lb = F(0, 1)
        ub = F(b, 1)
        Pm2, Pm1 = 0, 1
        Qm2, Qm1 = 1, 0
        def interval_int_bounds(lb, ub, m):
            lo = (lb.numerator // lb.denominator) + 1
            ceil_ub = (ub.numerator + ub.denominator - 1) // ub.denominator
            hi = ceil_ub - 1
            lo = max(lo, 1)
            hi = min(hi, m)
            return lo, hi
        lo_int, hi_int = interval_int_bounds(lb, ub, m)
        if lo_int > hi_int:
            return None, 0
        best_lb, best_ub = lb, ub
        max_k = 2
        k = 3
        while True:
            Pk = c * Pm2 - Pm1
            Qk = c * Qm2 - Qm1
            if Pk > 0:
                lb = max(lb, F(-Qk * a, Pk))
            elif Pk < 0:
                ub = min(ub, F(-Qk * a, Pk))
            else:
                val = Qk * a
                if not (0 < val < b):
                    break
            if Pk > 0:
                ub = min(ub, F(b - Qk * a, Pk))
            elif Pk < 0:
                lb = max(lb, F(b - Qk * a, Pk))
            else:
                val = Qk * a
                if not (0 < val < b):
                    break
            lo_int, hi_int = interval_int_bounds(lb, ub, m)
            if lo_int <= hi_int:
                best_lb, best_ub = lb, ub
                max_k = k
                Pm2, Pm1 = Pm1, Pk
                Qm2, Qm1 = Qm1, Qk
                k += 1
            else:
                break
        lo_int, hi_int = interval_int_bounds(best_lb, best_ub, m)
        if lo_int > hi_int:
            return None, 0
        x_ans = lo_int
        return x_ans, max_k

    try:
        a = int(assign.get('a'))
        b = int(assign.get('b'))
        c = int(assign.get('c'))
        m = int(assign.get('m'))
    except Exception:
        return (False, None)  # invalid assignment types

    if not (a > 0 and b > 0 and c >= 2 and m >= 1 and a < b):
        return (False, None)  # domain constraints violated

    x_ans, L = best_x_and_length(a, b, c, m)
    if x_ans is None:
        return (False, None)  # no feasible x exists; invalid instance

    # Enforce a difficulty floor: require non-trivial horizon (at least 8 terms survive)
    if L < 8:
        return (False, None)  # too easy; reject instance

    return True, x_ans
